ID3(Examples, Attributes):
  if all examples have the same class c: return leaf(c)
  if Attributes is empty: return leaf(majority class)
  A <- attribute in Attributes with the highest IG(Examples, A)
  create node testing A
  for each value v of A:
    Sv <- examples with A = v
    if Sv is empty: add leaf(majority class of Examples)
    else: add subtree ID3(Sv, Attributes - {A})
  return node
